#!/bin/bash
# Run a shadow driver .st (generated by Supervisor>>driverForCandidate:repro:out:)
# in a FRESH VM over the pristine base image. The live VM is never touched.
# The driver installs the kernel, replays journal[1..N], applies the candidate,
# runs repro + suite, writes its JSON verdict to $OUT, and quits without saving.
PHARO=${PHARO_BIN:-/opt/pharo/pharo-vm/pharo}
BASE=${BASE_IMAGE:-/opt/pharo/pharo.image}
TIMEOUT=${SHADOW_TIMEOUT:-120}

[ -z "$DRIVER" ] && { echo "DRIVER env required" >&2; exit 2; }
timeout "$TIMEOUT" "$PHARO" --headless "$BASE" eval "$(cat "$DRIVER")"
# pharo exit status is irrelevant; callers judge the OUT file contents.
exit 0
